import{bQ as d,aL as e,u as o,G as c}from"./chunks/framework.CNL6o8_w.js";const p=JSON.parse('{"title":"BLE Mesh 指令帧","description":"","frontmatter":{},"headers":[],"relativePath":"lightsmart/reference/ble-frame.md","filePath":"lightsmart/reference/ble-frame.md"}'),a={name:"lightsmart/reference/ble-frame.md"};function r(h,t,s,l,n,i){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="ble-mesh-指令帧" tabindex="-1">BLE Mesh 指令帧 <a class="header-anchor" href="#ble-mesh-指令帧" aria-label="Permalink to &quot;BLE Mesh 指令帧&quot;">​</a></h1><h2 id="帧结构" tabindex="-1">帧结构 <a class="header-anchor" href="#帧结构" aria-label="Permalink to &quot;帧结构&quot;">​</a></h2><p>所有 BLE Mesh 指令均为 hex 字符串，格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>53 &lt;命令体&gt; &lt;签名&gt;</span></span></code></pre></div><ul><li><code>53</code> — 帧头</li><li>命令体 — 由 <code>genCommand()</code> 生成</li><li>签名 — 由 <code>signCommand()</code> 生成（防篡改）</li></ul><h2 id="msgtype-定义" tabindex="-1">msgType 定义 <a class="header-anchor" href="#msgtype-定义" aria-label="Permalink to &quot;msgType 定义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>msgType</th><th>说明</th></tr></thead><tbody><tr><td><code>30</code></td><td>控制指令（ble_in 下发）</td></tr><tr><td><code>80</code></td><td>状态响应（ble_out 上报）</td></tr><tr><td><code>32</code></td><td>查询指令</td></tr><tr><td><code>0c</code></td><td>登录指令</td></tr><tr><td><code>04</code></td><td>Mesh 配置</td></tr><tr><td><code>01</code></td><td>BLE 名称设置</td></tr><tr><td><code>12</code></td><td>扫描指令</td></tr><tr><td><code>92</code></td><td>设备列表上报</td></tr></tbody></table><h2 id="gencommand-指令对照表" tabindex="-1">genCommand 指令对照表 <a class="header-anchor" href="#gencommand-指令对照表" aria-label="Permalink to &quot;genCommand 指令对照表&quot;">​</a></h2><p><code>genCommand(type, data)</code> 生成 <code>53</code> + 命令体 + 签名。</p><h3 id="命令体格式" tabindex="-1">命令体格式 <a class="header-anchor" href="#命令体格式" aria-label="Permalink to &quot;命令体格式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>30 &lt;cmdLen&gt; &lt;naddr&gt; &lt;msgType&gt; &lt;参数&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>说明</th></tr></thead><tbody><tr><td><code>30</code></td><td>1 字节</td><td>固定前缀</td></tr><tr><td>cmdLen</td><td>1 字节</td><td>后续数据长度（<code>04</code> 或 <code>05</code>）</td></tr><tr><td>naddr</td><td>1 字节</td><td>设备网络地址</td></tr><tr><td>msgType</td><td>1 字节</td><td>指令类型码</td></tr><tr><td>参数</td><td>可变</td><td>指令参数</td></tr></tbody></table><h3 id="开关控制" tabindex="-1">开关控制 <a class="header-anchor" href="#开关控制" aria-label="Permalink to &quot;开关控制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>type</th><th>cmdLen</th><th>msgType</th><th>参数格式</th><th>示例</th></tr></thead><tbody><tr><td><code>controlSwitch</code></td><td><code>04</code>/<code>05</code></td><td><code>02</code>/<code>45</code></td><td><code>&lt;status_byte&gt;</code> / <code>&lt;status_byte&gt;&lt;status_byte2&gt;</code></td><td><code>533004aabb02ff02</code> + sign</td></tr><tr><td><code>controlPlugcardSwitch</code></td><td><code>04</code></td><td><code>48</code></td><td><code>&lt;status_byte&gt;</code></td><td>插卡取电</td></tr></tbody></table><p><strong>status_byte 编码</strong>（4 路）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bit 7 6 5 4 3 2 1 0</span></span>
<span class="line"><span>     [4][3][2][1]    每路 2 bit: 10=开, 01=关, 00=不变</span></span></code></pre></div><p>8 路开关（oe=true）使用 cmdLen=<code>05</code>、msgType=<code>45</code>，额外一个字节编码 5-8 路。</p><h3 id="亮度控制" tabindex="-1">亮度控制 <a class="header-anchor" href="#亮度控制" aria-label="Permalink to &quot;亮度控制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>type</th><th>cmdLen</th><th>msgType</th><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>setBrightnessPercentage</code></td><td><code>04</code></td><td><code>03</code></td><td><code>&lt;val&gt;</code></td><td>设置亮度百分比</td></tr><tr><td><code>increaseBrightnessPercentage</code></td><td><code>04</code></td><td><code>2f</code></td><td><code>&lt;val&gt;</code></td><td>增加亮度</td></tr><tr><td><code>decreaseBrightnessPercentage</code></td><td><code>04</code></td><td><code>30</code></td><td><code>&lt;val&gt;</code></td><td>降低亮度</td></tr><tr><td><code>setBrightnessV2</code></td><td><code>05</code></td><td><code>9c</code></td><td><code>&lt;index&gt;&lt;val&gt;</code></td><td>设置子灯亮度</td></tr><tr><td><code>increaseBrightnessV2</code></td><td><code>05</code></td><td><code>a1</code></td><td><code>&lt;index&gt;&lt;val&gt;</code></td><td>增加子灯亮度</td></tr><tr><td><code>decreaseBrightnessV2</code></td><td><code>05</code></td><td><code>a2</code></td><td><code>&lt;index&gt;&lt;val&gt;</code></td><td>降低子灯亮度</td></tr></tbody></table><h3 id="色温控制" tabindex="-1">色温控制 <a class="header-anchor" href="#色温控制" aria-label="Permalink to &quot;色温控制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>type</th><th>cmdLen</th><th>msgType</th><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>setColorTemperature</code></td><td><code>04</code></td><td><code>04</code></td><td><code>&lt;val&gt;</code></td><td>设置色温</td></tr><tr><td><code>increaseColorTemperature</code></td><td><code>04</code></td><td><code>31</code></td><td><code>&lt;val&gt;</code></td><td>增加色温</td></tr><tr><td><code>decreaseColorTemperature</code></td><td><code>04</code></td><td><code>32</code></td><td><code>&lt;val&gt;</code></td><td>降低色温</td></tr><tr><td><code>setColorTemperatureV2</code></td><td><code>05</code></td><td><code>9d</code></td><td><code>&lt;index&gt;&lt;val&gt;</code></td><td>设置子灯色温</td></tr><tr><td><code>increaseColorTemperatureV2</code></td><td><code>05</code></td><td><code>a5</code></td><td><code>&lt;index&gt;&lt;val&gt;</code></td><td>增加子灯色温</td></tr><tr><td><code>decreaseColorTemperatureV2</code></td><td><code>05</code></td><td><code>a6</code></td><td><code>&lt;index&gt;&lt;val&gt;</code></td><td>降低子灯色温</td></tr></tbody></table><h3 id="窗帘控制" tabindex="-1">窗帘控制 <a class="header-anchor" href="#窗帘控制" aria-label="Permalink to &quot;窗帘控制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>type</th><th>cmdLen</th><th>msgType</th><th>参数</th><th>hex 示例</th></tr></thead><tbody><tr><td><code>openCurtain</code></td><td><code>04</code></td><td><code>05</code></td><td><code>01</code></td><td><code>533004aabb0501</code></td></tr><tr><td><code>closeCurtain</code></td><td><code>04</code></td><td><code>05</code></td><td><code>02</code></td><td><code>533004aabb0502</code></td></tr><tr><td><code>stopCurtain</code></td><td><code>04</code></td><td><code>05</code></td><td><code>03</code></td><td><code>533004aabb0503</code></td></tr><tr><td><code>openCurtainPos</code></td><td><code>04</code></td><td><code>06</code></td><td><code>&lt;pos&gt;</code></td><td><code>533004aabb0632</code> (pos=50)</td></tr><tr><td><code>closeCurtainPos</code></td><td><code>04</code></td><td><code>06</code></td><td><code>&lt;pos&gt;</code></td><td>同 openCurtainPos</td></tr></tbody></table><h3 id="空调控制" tabindex="-1">空调控制 <a class="header-anchor" href="#空调控制" aria-label="Permalink to &quot;空调控制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>type</th><th>cmdLen</th><th>msgType</th><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>openAC</code></td><td><code>04</code></td><td><code>02</code></td><td><code>02</code></td><td>开空调</td></tr><tr><td><code>closeAC</code></td><td><code>04</code></td><td><code>02</code></td><td><code>01</code></td><td>关空调</td></tr><tr><td><code>setACMode</code></td><td><code>04</code></td><td><code>1d</code></td><td><code>&lt;mode&gt;</code></td><td>mode: 1=cold, 2=warm, 3=fan, 4=auto</td></tr><tr><td><code>setACTemperature</code></td><td><code>04</code></td><td><code>1b</code></td><td><code>&lt;val&gt;</code></td><td>设置温度</td></tr><tr><td><code>increaseACTemperature</code></td><td><code>04</code></td><td><code>33</code></td><td><code>&lt;val&gt;</code></td><td>增加温度</td></tr><tr><td><code>decreaseACTemperature</code></td><td><code>04</code></td><td><code>34</code></td><td><code>&lt;val&gt;</code></td><td>降低温度</td></tr><tr><td><code>setFanSpeed</code></td><td><code>04</code></td><td><code>1c</code></td><td><code>&lt;speed&gt;</code></td><td>speed: 1=high, 2=middle, 3=low, 4=auto</td></tr><tr><td><code>increaseFanSpeed</code></td><td><code>04</code></td><td><code>35</code></td><td><code>01</code></td><td>增加风速</td></tr><tr><td><code>decreaseFanSpeed</code></td><td><code>04</code></td><td><code>36</code></td><td><code>01</code></td><td>降低风速</td></tr></tbody></table><h3 id="红外控制" tabindex="-1">红外控制 <a class="header-anchor" href="#红外控制" aria-label="Permalink to &quot;红外控制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>type</th><th>cmdLen</th><th>msgType</th><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>ir_transmitter</code></td><td><code>07</code></td><td><code>8f</code></td><td><code>&lt;ir_data&gt;</code></td><td>红外指令</td></tr></tbody></table><p><strong>ir_data 格式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;study&gt;&lt;cmd_id&gt;&lt;delay&gt;&lt;reserved&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>说明</th></tr></thead><tbody><tr><td>study</td><td>1 字节</td><td><code>00</code>=发送，<code>01</code>=学习</td></tr><tr><td>cmd_id</td><td>1 字节</td><td>红外指令码（见下表）</td></tr><tr><td>delay</td><td>1 字节</td><td>延时（单位 100ms）</td></tr><tr><td>reserved</td><td>1 字节</td><td>保留</td></tr></tbody></table><p><strong>红外指令码对照</strong>：</p><table tabindex="0"><thead><tr><th>动作</th><th>TV</th><th>机顶盒</th></tr></thead><tbody><tr><td>turn_on</td><td><code>0d</code></td><td><code>2f</code></td></tr><tr><td>turn_off</td><td><code>0d</code></td><td><code>2f</code></td></tr><tr><td>increase_volume</td><td><code>04</code></td><td><code>26</code></td></tr><tr><td>decrease_volume</td><td><code>0e</code></td><td><code>30</code></td></tr><tr><td>set_volume_mute</td><td><code>00</code></td><td><code>22</code></td></tr><tr><td>increase_channel</td><td><code>05</code></td><td><code>27</code></td></tr><tr><td>decrease_channel</td><td><code>0f</code></td><td><code>31</code></td></tr></tbody></table><h3 id="其他指令" tabindex="-1">其他指令 <a class="header-anchor" href="#其他指令" aria-label="Permalink to &quot;其他指令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>type</th><th>cmdLen</th><th>msgType</th><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>setColorRgb</code></td><td><code>06</code></td><td><code>4c</code></td><td><code>&lt;rgb&gt;</code></td><td>RGB 灯颜色</td></tr><tr><td><code>disableDevice</code></td><td><code>04</code></td><td><code>bc c0 26</code></td><td><code>&lt;01/00&gt;</code></td><td>禁用/启用设备</td></tr></tbody></table><h3 id="场景执行" tabindex="-1">场景执行 <a class="header-anchor" href="#场景执行" aria-label="Permalink to &quot;场景执行&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>genExecuteScene(id) → 53 30 04 bc c0 01 &lt;id&gt; &lt;sign&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>53</code></td><td>帧头</td></tr><tr><td><code>30</code></td><td>控制指令</td></tr><tr><td><code>04</code></td><td>数据长度</td></tr><tr><td><code>bc c0</code></td><td>场景指令标识</td></tr><tr><td><code>01</code></td><td>固定</td></tr><tr><td><code>&lt;id&gt;</code></td><td>场景 ID（1 字节 hex）</td></tr><tr><td><code>&lt;sign&gt;</code></td><td>签名</td></tr></tbody></table><h2 id="naddr-编码" tabindex="-1">naddr 编码 <a class="header-anchor" href="#naddr-编码" aria-label="Permalink to &quot;naddr 编码&quot;">​</a></h2><p><code>encodeNaddr(data.naddr)</code> 将设备的网络地址编码为 1 字节 hex。naddr 是 BLE Mesh 中的单播地址，范围 0x0001-0x7FFF，编码时取低 8 位。</p><h2 id="签名" tabindex="-1">签名 <a class="header-anchor" href="#签名" aria-label="Permalink to &quot;签名&quot;">​</a></h2><p><code>signCommand(cmd)</code> 对命令体计算签名，附加在末尾。签名算法用于防止指令篡改，网关收到指令后会验证签名。</p>`,41)])])}const g=d(a,[["render",r]]);export{p as __pageData,g as default};
